package in.gov.fci.payroll.platform.notification;

/**
 * The member's document is not produced yet (SRS-NF-5 / SRS-NF-7: the payslip and Form 16 PDFs are
 * generated by a batch job after the lock or the C-10 release and stored): the e-mail is deferred,
 * its attempt not spent, and tried again later (OD-148). Names no member (R-PII).
 */
public class DocumentNotReadyException extends RuntimeException {

    private static final long serialVersionUID = 1L;

    public DocumentNotReadyException(String message) {
        super(message);
    }
}
